using System.ComponentModel.DataAnnotations;
using CreatorPay.Application.Accounts;
using CreatorPay.Application.Authentication;
using CreatorPay.Application.CustomerVerification;
using CreatorPay.Application.Organization;
using CreatorPay.Domain.Common;
using CreatorPay.Domain.Entities;
using CreatorPay.Domain.Enums;
using CreatorPay.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace CreatorPay.Infrastructure.Organization;

public sealed class OrganizationService(ApplicationDbContext db, IPasswordHasher passwords, ITokenService tokens, IUtcClock clock, PasswordPolicyValidator passwordPolicy, IOptions<StaffInvitationOptions> options, IPhoneOtpService phoneOtp) : IOrganizationService
{
    public async Task<OrganizationResult<IReadOnlyList<LocationResponse>>> GetLocationsAsync(Guid merchantId, bool activeOnly, CancellationToken ct)
    { var q = db.MerchantLocations.AsNoTracking().Where(x => x.MerchantId == merchantId); if (activeOnly) q = q.Where(x => x.IsActive); return OrganizationResult<IReadOnlyList<LocationResponse>>.Ok(await q.OrderBy(x => x.Name).Select(x => Loc(x)).ToListAsync(ct)); }
    public async Task<OrganizationResult<LocationResponse>> GetLocationAsync(Guid merchantId, Guid id, CancellationToken ct)
    { var x = await db.MerchantLocations.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); return x is null ? OrganizationResult<LocationResponse>.Fail("Location not found.", 404) : OrganizationResult<LocationResponse>.Ok(Loc(x)); }
    public async Task<OrganizationResult<LocationResponse>> CreateLocationAsync(Guid merchantId, Guid actor, LocationRequest r, CancellationToken ct)
    { var e = ValidateLocation(r); if (e is not null) return OrganizationResult<LocationResponse>.Fail(e); if (await DuplicateLocation(merchantId, r.Name, null, ct)) return OrganizationResult<LocationResponse>.Fail("An active location with this name already exists.", 409); var now = clock.UtcNow; var x = new MerchantLocation { Id = Guid.NewGuid(), MerchantId = merchantId, IsActive = true, CreatedAtUtc = now, CreatedBy = actor.ToString() }; Map(x, r); db.Add(x); Audit(merchantId, actor, "LocationCreated", x.Id.ToString(), now); await db.SaveChangesAsync(ct); return OrganizationResult<LocationResponse>.Ok(Loc(x), 201); }
    public async Task<OrganizationResult<LocationResponse>> UpdateLocationAsync(Guid merchantId, Guid actor, Guid id, LocationRequest r, CancellationToken ct)
    { var x = await db.MerchantLocations.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult<LocationResponse>.Fail("Location not found.", 404); var e = ValidateLocation(r); if (e is not null) return OrganizationResult<LocationResponse>.Fail(e); if (x.IsActive && await DuplicateLocation(merchantId, r.Name, id, ct)) return OrganizationResult<LocationResponse>.Fail("An active location with this name already exists.", 409); Map(x, r); Touch(x, actor); Audit(merchantId, actor, "LocationUpdated", id.ToString(), clock.UtcNow); await db.SaveChangesAsync(ct); return OrganizationResult<LocationResponse>.Ok(Loc(x)); }
    public async Task<OrganizationResult> SetLocationStatusAsync(Guid merchantId, Guid actor, Guid id, bool active, CancellationToken ct)
    { var x = await db.MerchantLocations.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult.Fail("Location not found.", 404); if (active && await DuplicateLocation(merchantId, x.Name, id, ct)) return OrganizationResult.Fail("An active location with this name already exists.", 409); x.IsActive = active; Touch(x, actor); Audit(merchantId, actor, active ? "LocationActivated" : "LocationDeactivated", id.ToString(), clock.UtcNow); await db.SaveChangesAsync(ct); return OrganizationResult.Ok(); }
    public async Task<OrganizationResult<IReadOnlyList<StaffResponse>>> GetStaffAsync(Guid merchantId, UserRole role, CancellationToken ct)
    { if (!StaffRole(role)) return OrganizationResult<IReadOnlyList<StaffResponse>>.Fail("Invalid staff role."); var rows = role == UserRole.Supervisor ? await db.Supervisors.AsNoTracking().Where(x => x.MerchantId == merchantId).OrderBy(x => x.LastName).Select(x => new StaffSeed(x.Id, x.FirstName, x.LastName, x.Email, x.PhoneNumber, x.IsActive)).ToListAsync(ct) : await db.Cashiers.AsNoTracking().Where(x => x.MerchantId == merchantId).OrderBy(x => x.LastName).Select(x => new StaffSeed(x.Id, x.FirstName, x.LastName, x.Email, x.PhoneNumber, x.IsActive)).ToListAsync(ct); var result = new List<StaffResponse>(); foreach (var x in rows) result.Add(await ToStaff(x, role, ct)); return OrganizationResult<IReadOnlyList<StaffResponse>>.Ok(result); }
    public async Task<OrganizationResult<StaffResponse>> GetStaffAsync(Guid merchantId, UserRole role, Guid id, CancellationToken ct)
    { var seed = await Seed(merchantId, role, id, ct); return seed is null ? OrganizationResult<StaffResponse>.Fail("Staff member not found.", 404) : OrganizationResult<StaffResponse>.Ok(await ToStaff(seed, role, ct)); }
    public async Task<OrganizationResult<StaffResponse>> CreateCashierAsync(Guid merchantId, Guid actor, CreateCashierRequest r, CancellationToken ct)
    {
        _ = phoneOtp; // retained for constructor compatibility while OTP registration is disabled
        var staffError = ValidateStaff(r.FirstName, r.LastName, "cashier@weymela.local", r.PhoneNumber); if (staffError is not null) return OrganizationResult<StaffResponse>.Fail(staffError);
        if (r.TemporaryPassword != r.Confirmation) return OrganizationResult<StaffResponse>.Fail("Temporary password confirmation does not match."); var passwordErrors = passwordPolicy.Validate(r.TemporaryPassword); if (passwordErrors.Count > 0) return OrganizationResult<StaffResponse>.Fail(string.Join(" ", passwordErrors));
        var phone = NormalizePhone(r.PhoneNumber); if (await db.UserAccounts.AnyAsync(x => x.NormalizedPhoneNumber == phone, ct)) return OrganizationResult<StaffResponse>.Fail("Phone number is already registered.", 409); var login = r.Email?.Trim() ?? ""; var normalized = NormalizeEmail(login); if (normalized.Length > 0 && await db.UserAccounts.AnyAsync(x => x.NormalizedEmail == normalized, ct)) return OrganizationResult<StaffResponse>.Fail("Email is already registered.", 409);
        if (r.LocationName?.Trim().Length > 200) return OrganizationResult<StaffResponse>.Fail("Location / Branch must not exceed 200 characters.");
        if (r.LocationId.HasValue && !await db.MerchantLocations.AnyAsync(x => x.Id == r.LocationId.Value && x.MerchantId == merchantId && x.IsActive, ct)) return OrganizationResult<StaffResponse>.Fail("The assigned location must be active and belong to the Business.");
        var now = clock.UtcNow;
        var cashier = new Cashier { Id = Guid.NewGuid(), MerchantId = merchantId, FirstName = r.FirstName.Trim(), LastName = r.LastName.Trim(), Email = login, NormalizedEmail = normalized, PhoneNumber = phone, NormalizedPhoneNumber = phone, IsActive = false, CreatedAtUtc = now, CreatedBy = actor.ToString() }; db.Add(cashier);
        if (r.LocationId.HasValue) db.Add(new CashierLocationAssignment { Id = Guid.NewGuid(), CashierId = cashier.Id, MerchantLocationId = r.LocationId.Value, IsActive = true, IsPrimary = true, CreatedAtUtc = now, CreatedBy = actor.ToString() });
        var user = new UserAccount { Id = Guid.NewGuid(), Email = login, NormalizedEmail = normalized, PhoneNumber = phone, NormalizedPhoneNumber = phone, Role = UserRole.Cashier, Status = AccountStatus.Active, MerchantId = merchantId, CashierId = cashier.Id, IsEmailVerified = false, IsPhoneVerified = false, CreatedAtUtc = now, CreatedBy = actor.ToString() }; user.PasswordHash = passwords.Hash(user, r.TemporaryPassword); db.Add(user); cashier.IsActive = true; Audit(merchantId, actor, "CashierAccountCreated", cashier.Id.ToString(), now); await db.SaveChangesAsync(ct); return await GetStaffAsync(merchantId, UserRole.Cashier, cashier.Id, ct);
    }
    public async Task<OrganizationResult<InvitationResponse>> InviteAsync(Guid merchantId, Guid actor, UserRole role, StaffInvitationRequest r, CancellationToken ct)
    { if (!StaffRole(role)) return OrganizationResult<InvitationResponse>.Fail("Business invitations are limited to Supervisor and Cashier.", 403); var e = ValidateStaff(r.FirstName, r.LastName, r.Email, r.PhoneNumber); if (e is not null) return OrganizationResult<InvitationResponse>.Fail(e); var normalized = NormalizeEmail(r.Email); if (await db.UserAccounts.AnyAsync(x => x.NormalizedEmail == normalized, ct) || await db.StaffInvitations.AnyAsync(x => x.NormalizedEmail == normalized && x.AcceptedAtUtc == null && x.RevokedAtUtc == null && x.ExpiresAtUtc > clock.UtcNow, ct)) return OrganizationResult<InvitationResponse>.Fail("Email is already registered or has a pending invitation.", 409); var ids = (r.LocationIds ?? []).Distinct().ToArray(); if (role == UserRole.Cashier && ids.Length > 1) return OrganizationResult<InvitationResponse>.Fail("Assign at most one Business location to the Cashier."); if (!await LocationsAreActive(merchantId, ids, ct)) return OrganizationResult<InvitationResponse>.Fail("Every assigned location must be active and belong to the Business.", 400); var now = clock.UtcNow; Entity staff; if (role == UserRole.Supervisor) { var x = new Supervisor { Id = Guid.NewGuid(), MerchantId = merchantId, FirstName = r.FirstName.Trim(), LastName = r.LastName.Trim(), Email = r.Email.Trim(), NormalizedEmail = normalized, PhoneNumber = r.PhoneNumber.Trim(), NormalizedPhoneNumber = NormalizePhone(r.PhoneNumber), IsActive = false, CreatedAtUtc = now, CreatedBy = actor.ToString() }; staff = x; db.Add(x); foreach (var id in ids) db.Add(new SupervisorLocationAssignment { Id = Guid.NewGuid(), SupervisorId = x.Id, MerchantLocationId = id, IsActive = true, CreatedAtUtc = now, CreatedBy = actor.ToString() }); } else { var x = new Cashier { Id = Guid.NewGuid(), MerchantId = merchantId, FirstName = r.FirstName.Trim(), LastName = r.LastName.Trim(), Email = r.Email.Trim(), NormalizedEmail = normalized, PhoneNumber = r.PhoneNumber.Trim(), NormalizedPhoneNumber = NormalizePhone(r.PhoneNumber), IsActive = false, CreatedAtUtc = now, CreatedBy = actor.ToString() }; staff = x; db.Add(x); foreach (var id in ids) db.Add(new CashierLocationAssignment { Id = Guid.NewGuid(), CashierId = x.Id, MerchantLocationId = id, IsActive = true, IsPrimary = true, CreatedAtUtc = now, CreatedBy = actor.ToString() }); } var raw = tokens.CreateOpaqueToken(); var invitation = new StaffInvitation { Id = Guid.NewGuid(), MerchantId = merchantId, Email = r.Email.Trim(), NormalizedEmail = normalized, UserRole = role, TokenHash = tokens.HashToken(raw), ExpiresAtUtc = now.AddHours(options.Value.LifetimeHours), InvitedByUserId = actor, SupervisorId = role == UserRole.Supervisor ? staff.Id : null, CashierId = role == UserRole.Cashier ? staff.Id : null, CreatedAtUtc = now, CreatedBy = actor.ToString() }; db.Add(invitation); Audit(merchantId, actor, $"{role}Invited", invitation.Id.ToString(), now); await db.SaveChangesAsync(ct); var invitationUrl = $"{options.Value.WebBaseUrl.TrimEnd('/')}/staff-invitations/accept?token={Uri.EscapeDataString(raw)}"; return OrganizationResult<InvitationResponse>.Ok(new(invitation.Id, invitation.Email, role, invitation.ExpiresAtUtc, invitationUrl, options.Value.ReturnDevelopmentToken ? raw : null), 201); }
    public async Task<OrganizationResult<StaffResponse>> UpdateStaffAsync(Guid merchantId, Guid actor, UserRole role, Guid id, StaffProfileRequest r, CancellationToken ct)
    { var e = ValidateStaff(r.FirstName, r.LastName, "staff@example.com", r.PhoneNumber); if (e is not null) return OrganizationResult<StaffResponse>.Fail(e); if (role == UserRole.Supervisor) { var x = await db.Supervisors.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult<StaffResponse>.Fail("Staff member not found.", 404); x.FirstName = r.FirstName.Trim(); x.LastName = r.LastName.Trim(); x.PhoneNumber = r.PhoneNumber.Trim(); x.NormalizedPhoneNumber = NormalizePhone(r.PhoneNumber); Touch(x, actor); } else if (role == UserRole.Cashier) { var x = await db.Cashiers.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult<StaffResponse>.Fail("Staff member not found.", 404); x.FirstName = r.FirstName.Trim(); x.LastName = r.LastName.Trim(); x.PhoneNumber = r.PhoneNumber.Trim(); x.NormalizedPhoneNumber = NormalizePhone(r.PhoneNumber); Touch(x, actor); } else return OrganizationResult<StaffResponse>.Fail("Invalid staff role."); Audit(merchantId, actor, $"{role}Updated", id.ToString(), clock.UtcNow); await db.SaveChangesAsync(ct); return await GetStaffAsync(merchantId, role, id, ct); }
    public Task<OrganizationResult> AssignSupervisorAsync(Guid merchantId, Guid actor, Guid id, SupervisorLocationsRequest r, CancellationToken ct) => Assign(merchantId, actor, UserRole.Supervisor, id, r.LocationIds, null, ct);
    public Task<OrganizationResult> AssignCashierAsync(Guid merchantId, Guid actor, Guid id, CashierLocationsRequest r, CancellationToken ct) => Assign(merchantId, actor, UserRole.Cashier, id, r.LocationIds, r.PrimaryLocationId, ct);
    public async Task<OrganizationResult> SetStaffStatusAsync(Guid merchantId, Guid actor, UserRole role, Guid id, bool active, CancellationToken ct)
    { UserAccount? user; if (role == UserRole.Supervisor) { var x = await db.Supervisors.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult.Fail("Staff member not found.", 404); x.IsActive = active; Touch(x, actor); user = await db.UserAccounts.SingleOrDefaultAsync(u => u.SupervisorId == id, ct); } else if (role == UserRole.Cashier) { var x = await db.Cashiers.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult.Fail("Staff member not found.", 404); x.IsActive = active; Touch(x, actor); user = await db.UserAccounts.SingleOrDefaultAsync(u => u.CashierId == id, ct); } else return OrganizationResult.Fail("Invalid staff role."); if (user is not null) { user.Status = active ? AccountStatus.Active : AccountStatus.Suspended; if (!active) { var now = clock.UtcNow; foreach (var token in await db.RefreshTokens.Where(x => x.UserAccountId == user.Id && x.RevokedAtUtc == null).ToListAsync(ct)) { token.RevokedAtUtc = now; token.RevokedReason = "Staff deactivated"; } } } Audit(merchantId, actor, $"{role}{(active ? "Activated" : "Deactivated")}", id.ToString(), clock.UtcNow); await db.SaveChangesAsync(ct); return OrganizationResult.Ok(); }
    public async Task<OrganizationResult> RevokeInvitationAsync(Guid merchantId, Guid actor, Guid id, CancellationToken ct)
    { var x = await db.StaffInvitations.SingleOrDefaultAsync(x => x.Id == id && x.MerchantId == merchantId, ct); if (x is null) return OrganizationResult.Fail("Invitation not found.", 404); if (x.AcceptedAtUtc is not null || x.RevokedAtUtc is not null) return OrganizationResult.Fail("Invitation is no longer active.", 409); x.RevokedAtUtc = clock.UtcNow; Audit(merchantId, actor, "InvitationRevoked", id.ToString(), clock.UtcNow); await db.SaveChangesAsync(ct); return OrganizationResult.Ok(); }
    public async Task<OrganizationResult> AcceptInvitationAsync(AcceptStaffInvitationRequest r, CancellationToken ct)
    { if (r.Password != r.Confirmation) return OrganizationResult.Fail("Password confirmation does not match."); var errors = passwordPolicy.Validate(r.Password); if (errors.Count > 0) return OrganizationResult.Fail(string.Join(" ", errors)); return await InTransaction(async () => { var now = clock.UtcNow; var invitation = string.IsNullOrWhiteSpace(r.Token) ? null : await db.StaffInvitations.SingleOrDefaultAsync(x => x.TokenHash == tokens.HashToken(r.Token), ct); if (invitation is null || invitation.AcceptedAtUtc is not null || invitation.RevokedAtUtc is not null || invitation.ExpiresAtUtc <= now) { if (invitation is null) db.Add(new LoginAudit { Id = Guid.NewGuid(), WasSuccessful = false, FailureReason = "InvalidStaffInvitation", AttemptedAtUtc = now, CreatedAtUtc = now }); else Audit(invitation.MerchantId, null, "InvalidInvitationAcceptanceAttempt", invitation.Id.ToString(), now); await db.SaveChangesAsync(ct); return OrganizationResult.Fail(invitation?.RevokedAtUtc is not null ? "Invitation has been revoked." : invitation?.AcceptedAtUtc is not null ? "Invitation has already been used." : invitation is not null ? "Invitation has expired." : "Invitation token is invalid.", 400); } if (!StaffRole(invitation.UserRole) || await db.UserAccounts.AnyAsync(x => x.NormalizedEmail == invitation.NormalizedEmail, ct)) return OrganizationResult.Fail("Invitation cannot create this account.", 409); var user = new UserAccount { Id = Guid.NewGuid(), Email = invitation.Email, NormalizedEmail = invitation.NormalizedEmail, Role = invitation.UserRole, Status = AccountStatus.Active, MerchantId = invitation.MerchantId, SupervisorId = invitation.SupervisorId, CashierId = invitation.CashierId, IsEmailVerified = true, CreatedAtUtc = now }; user.PasswordHash = passwords.Hash(user, r.Password); db.Add(user); if (invitation.UserRole == UserRole.Supervisor) { var staff = await db.Supervisors.SingleAsync(x => x.Id == invitation.SupervisorId, ct); staff.IsActive = true; } else { var staff = await db.Cashiers.SingleAsync(x => x.Id == invitation.CashierId, ct); staff.IsActive = true; } invitation.AcceptedAtUtc = now; Audit(invitation.MerchantId, user.Id, $"{invitation.UserRole}InvitationAccepted", invitation.Id.ToString(), now); await db.SaveChangesAsync(ct); return OrganizationResult.Ok(); }, ct); }
    public async Task<OrganizationResult<InvitationPreviewResponse>> GetInvitationAsync(string token, CancellationToken ct)
    {
        var now = clock.UtcNow;
        var invitation = string.IsNullOrWhiteSpace(token) ? null : await db.StaffInvitations.AsNoTracking().SingleOrDefaultAsync(x => x.TokenHash == tokens.HashToken(token), ct);
        if (invitation is null || invitation.AcceptedAtUtc is not null || invitation.RevokedAtUtc is not null || invitation.ExpiresAtUtc <= now)
            return OrganizationResult<InvitationPreviewResponse>.Fail(invitation?.RevokedAtUtc is not null ? "Invitation has been revoked." : invitation?.AcceptedAtUtc is not null ? "Invitation has already been used." : invitation is not null ? "Invitation has expired." : "Invitation token is invalid.", 400);
        var business = await db.Merchants.AsNoTracking().Where(x => x.Id == invitation.MerchantId).Select(x => x.TradingName).SingleAsync(ct);
        var location = invitation.CashierId.HasValue
            ? await (from a in db.CashierLocationAssignments.AsNoTracking() join l in db.MerchantLocations.AsNoTracking() on a.MerchantLocationId equals l.Id where a.CashierId == invitation.CashierId && a.IsActive select l.Name).FirstOrDefaultAsync(ct)
            : await (from a in db.SupervisorLocationAssignments.AsNoTracking() join l in db.MerchantLocations.AsNoTracking() on a.MerchantLocationId equals l.Id where a.SupervisorId == invitation.SupervisorId && a.IsActive select l.Name).FirstOrDefaultAsync(ct);
        return OrganizationResult<InvitationPreviewResponse>.Ok(new(business, invitation.UserRole.ToString(), location ?? "Assigned after acceptance", invitation.ExpiresAtUtc));
    }
    public async Task<OrganizationResult<StaffResponse>> GetCurrentStaffAsync(Guid merchantId, UserRole role, Guid staffId, CancellationToken ct)
    { var staff = await Seed(merchantId, role, staffId, ct); if (staff is null) return OrganizationResult<StaffResponse>.Fail("Staff member not found.", 404); return OrganizationResult<StaffResponse>.Ok(await ToStaff(staff, role, ct)); }

    private async Task<OrganizationResult> Assign(Guid merchantId, Guid actor, UserRole role, Guid staffId, IReadOnlyList<Guid> requested, Guid? primary, CancellationToken ct)
    { var ids = requested.Distinct().ToArray(); if (primary.HasValue && !ids.Contains(primary.Value)) return OrganizationResult.Fail("Primary location must be one of the assigned locations."); if (await db.MerchantLocations.CountAsync(x => ids.Contains(x.Id) && x.MerchantId == merchantId && x.IsActive, ct) != ids.Length) return OrganizationResult.Fail("Every assigned location must be active and belong to the merchant."); if (await Seed(merchantId, role, staffId, ct) is null) return OrganizationResult.Fail("Staff member not found.", 404); var now = clock.UtcNow; if (role == UserRole.Supervisor) { var existing = await db.SupervisorLocationAssignments.Where(x => x.SupervisorId == staffId).ToListAsync(ct); foreach (var x in existing) { x.IsActive = ids.Contains(x.MerchantLocationId); Touch(x, actor); } foreach (var id in ids.Except(existing.Select(x => x.MerchantLocationId))) db.Add(new SupervisorLocationAssignment { Id = Guid.NewGuid(), SupervisorId = staffId, MerchantLocationId = id, IsActive = true, CreatedAtUtc = now, CreatedBy = actor.ToString() }); } else { var existing = await db.CashierLocationAssignments.Where(x => x.CashierId == staffId).ToListAsync(ct); foreach (var x in existing) { x.IsActive = ids.Contains(x.MerchantLocationId); x.IsPrimary = x.IsActive && x.MerchantLocationId == primary; Touch(x, actor); } foreach (var id in ids.Except(existing.Select(x => x.MerchantLocationId))) db.Add(new CashierLocationAssignment { Id = Guid.NewGuid(), CashierId = staffId, MerchantLocationId = id, IsActive = true, IsPrimary = id == primary, CreatedAtUtc = now, CreatedBy = actor.ToString() }); } Audit(merchantId, actor, $"{role}LocationAssignmentsChanged", staffId.ToString(), now); await db.SaveChangesAsync(ct); return OrganizationResult.Ok(); }
    private async Task<StaffSeed?> Seed(Guid merchantId, UserRole role, Guid id, CancellationToken ct) => role == UserRole.Supervisor ? await db.Supervisors.AsNoTracking().Where(x => x.Id == id && x.MerchantId == merchantId).Select(x => new StaffSeed(x.Id, x.FirstName, x.LastName, x.Email, x.PhoneNumber, x.IsActive)).SingleOrDefaultAsync(ct) : role == UserRole.Cashier ? await db.Cashiers.AsNoTracking().Where(x => x.Id == id && x.MerchantId == merchantId).Select(x => new StaffSeed(x.Id, x.FirstName, x.LastName, x.Email, x.PhoneNumber, x.IsActive)).SingleOrDefaultAsync(ct) : null;
    private async Task<StaffResponse> ToStaff(StaffSeed x, UserRole role, CancellationToken ct) { var locations = role == UserRole.Supervisor ? await (from a in db.SupervisorLocationAssignments.AsNoTracking() join l in db.MerchantLocations.AsNoTracking() on a.MerchantLocationId equals l.Id where a.SupervisorId == x.Id && a.IsActive select new StaffLocationResponse(l.Id, l.Name, l.IsActive, false)).ToListAsync(ct) : await (from a in db.CashierLocationAssignments.AsNoTracking() join l in db.MerchantLocations.AsNoTracking() on a.MerchantLocationId equals l.Id where a.CashierId == x.Id && a.IsActive select new StaffLocationResponse(l.Id, l.Name, l.IsActive, a.IsPrimary)).ToListAsync(ct); var merchantId = role == UserRole.Supervisor ? await db.Supervisors.Where(s => s.Id == x.Id).Select(s => s.MerchantId).SingleAsync(ct) : await db.Cashiers.Where(c => c.Id == x.Id).Select(c => c.MerchantId).SingleAsync(ct); var business = await db.Merchants.Where(m => m.Id == merchantId).Select(m => m.TradingName).SingleAsync(ct); var username = role == UserRole.Cashier && x.Email.EndsWith("@cashier.weymela.local", StringComparison.OrdinalIgnoreCase) ? x.Email[..x.Email.IndexOf('@')] : x.Email; var user = role == UserRole.Supervisor ? await db.UserAccounts.Where(u => u.SupervisorId == x.Id).SingleAsync(ct) : await db.UserAccounts.Where(u => u.CashierId == x.Id).SingleAsync(ct); var effective = EffectiveAccountStatus.FromStaff(user, x.Active, clock.UtcNow); return new(x.Id, x.First, x.Last, x.Email, username, x.Phone, x.Active, effective.EffectiveStatus, effective.EffectiveStatusReason, locations, business); }
    private async Task<bool> LocationsAreActive(Guid merchantId, Guid[] ids, CancellationToken ct)
    {
        var persisted = await db.MerchantLocations.Where(x => ids.Contains(x.Id) && x.MerchantId == merchantId && x.IsActive).Select(x => x.Id).ToListAsync(ct);
        return ids.All(id => persisted.Contains(id) || db.MerchantLocations.Local.Any(x => x.Id == id && x.MerchantId == merchantId && x.IsActive));
    }
    private Task<bool> DuplicateLocation(Guid merchant, string name, Guid? excluding, CancellationToken ct) { var n = name.Trim().ToUpper(); return db.MerchantLocations.AnyAsync(x => x.MerchantId == merchant && x.IsActive && x.Name.ToUpper() == n && (!excluding.HasValue || x.Id != excluding), ct); }
    private static string? ValidateLocation(LocationRequest r) { if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Trim().Length > 200) return "Location name is required and must not exceed 200 characters."; if (string.IsNullOrWhiteSpace(r.AddressLine1) || string.IsNullOrWhiteSpace(r.City) || string.IsNullOrWhiteSpace(r.CountryCode) || string.IsNullOrWhiteSpace(r.TimeZoneId)) return "Address line 1, city, country code, and time zone are required."; if (r.CountryCode.Trim().Length != 2) return "Country code must contain two letters."; if (r.Latitude.HasValue != r.Longitude.HasValue) return "Latitude and longitude must be provided together."; if (r.Latitude is < -90 or > 90 || r.Longitude is < -180 or > 180) return "Location coordinates are invalid."; try { _ = TimeZoneInfo.FindSystemTimeZoneById(r.TimeZoneId.Trim()); } catch { return "Time zone is invalid."; } return null; }
    private static string? ValidateStaff(string first, string last, string email, string phone) { if (string.IsNullOrWhiteSpace(first) || string.IsNullOrWhiteSpace(last)) return "First and last name are required."; if (!new EmailAddressAttribute().IsValid(email?.Trim())) return "Email is invalid."; var digits = NormalizePhone(phone); return digits.Length is < 8 or > 15 ? "Phone number must contain 8 to 15 digits." : null; }
    private static void Map(MerchantLocation x, LocationRequest r) { x.Name = r.Name.Trim(); x.AddressLine1 = r.AddressLine1.Trim(); x.AddressLine2 = Clean(r.AddressLine2); x.City = r.City.Trim(); x.Region = Clean(r.Region); x.CountryCode = r.CountryCode.Trim().ToUpperInvariant(); x.TimeZoneId = r.TimeZoneId.Trim(); x.Latitude = r.Latitude; x.Longitude = r.Longitude; }
    private static LocationResponse Loc(MerchantLocation x) => new(x.Id, x.Name, x.AddressLine1, x.AddressLine2, x.City, x.Region, x.CountryCode, x.TimeZoneId, x.IsActive, x.Latitude, x.Longitude);
    private static bool StaffRole(UserRole r) => r is UserRole.Supervisor or UserRole.Cashier; private static string NormalizeEmail(string v) => v.Trim().ToUpperInvariant(); private static string NormalizePhone(string v) => EthiopianMobileNumber.Normalize(v); private static string? Clean(string? v) => string.IsNullOrWhiteSpace(v) ? null : v.Trim(); private void Audit(Guid merchant, Guid? actor, string type, string? detail, DateTime now) { if (merchant == Guid.Empty) return; db.Add(new MerchantAuditEvent { Id = Guid.NewGuid(), MerchantId = merchant, ActorUserAccountId = actor, EventType = type, Detail = detail, CreatedAtUtc = now, CreatedBy = actor?.ToString() }); }
    private static void Touch(Entity x, Guid actor) { x.UpdatedAtUtc = DateTime.UtcNow; x.UpdatedBy = actor.ToString(); }
    private async Task<T> InTransaction<T>(Func<Task<T>> action, CancellationToken ct) { await using var tx = await db.Database.BeginTransactionAsync(ct); var result = await action(); await tx.CommitAsync(ct); return result; }
    private sealed record StaffSeed(Guid Id, string First, string Last, string Email, string Phone, bool Active);
}
